class VideoSharingPlatform {
    private final Map<Integer, String> videos = new HashMap<>();
    private final Map<Integer, int[]> stats = new HashMap<>(); // likes, dislikes, views
    private final PriorityQueue<Integer> freed = new PriorityQueue<>();
    private int nextId = 0;

    public VideoSharingPlatform() {
    }

    public int upload(String video) {
        int id = freed.isEmpty() ? nextId++ : freed.poll();
        videos.put(id, video);
        stats.put(id, new int[3]);
        return id;
    }

    public void remove(int videoId) {
        if (videos.remove(videoId) != null) {
            stats.remove(videoId);
            freed.add(videoId);
        }
    }

    public String watch(int videoId, int startMinute, int endMinute) {
        String v = videos.get(videoId);
        if (v == null) return "-1";
        stats.get(videoId)[2]++;
        return v.substring(startMinute, Math.min(endMinute, v.length() - 1) + 1);
    }

    public void like(int videoId) {
        if (videos.containsKey(videoId)) stats.get(videoId)[0]++;
    }

    public void dislike(int videoId) {
        if (videos.containsKey(videoId)) stats.get(videoId)[1]++;
    }

    public int[] getLikesAndDislikes(int videoId) {
        int[] s = stats.get(videoId);
        return s == null ? new int[]{-1} : new int[]{s[0], s[1]};
    }

    public int getViews(int videoId) {
        int[] s = stats.get(videoId);
        return s == null ? -1 : s[2];
    }
}

